1	import type {
2	  ClientInterface,
3	  RoomInfo,
4	  RoomInterface,
5	  SyncServiceInterface,
6	} from "@unomed/react-native-matrix-sdk";
7	import { atom } from "jotai";
8	import { MatrixJotaiStore } from "../const/matrx-jotai-store";
9	
10	type VerificationStatus =
11	  | "idle"
12	  | "waiting"
13	  | "accepted"
14	  | "sasStarted"
15	  | "emojis"
16	  | "success"
17	  | "failed"
18	  | "cancelled"
19	  | "incomingRequest";
20	
21	type VerificationEmoji = {
22	  symbol: string;
23	  description: string;
24	};
25	
26	const roomList = atom<RoomInterface[]>([]);
27	
28	const roomInfoMap = atom<Map<string, RoomInfo>>(new Map());
29	
30	const roomListLoading = atom<boolean>(true);
31	
32	const matrixClient = atom<ClientInterface | null>(null);
33	
34	const syncService = atom<SyncServiceInterface | null>(null);
35	
36	const ignoredUsers = atom<string[] | null>(null);
37	
38	const verificationStatus = atom<VerificationStatus>("idle");
39	
40	const verificationEmojis = atom<VerificationEmoji[] | null>(null);
41	
42	const verificationSenderName = atom<string | null>(null);
43	
44	export const MatrixAtoms = {
45	  roomList,
46	  roomInfoMap,
47	  roomListLoading,
48	  matrixClient,
49	  syncService,
50	  ignoredUsers,
51	  verificationStatus,
52	  verificationEmojis,
53	  verificationSenderName,
54	};
55	
56	export const resetMatrixAtoms = () => {
57	  MatrixJotaiStore.set(roomList, []);
58	  MatrixJotaiStore.set(roomInfoMap, new Map());
59	  MatrixJotaiStore.set(roomListLoading, true);
60	  MatrixJotaiStore.set(matrixClient, null);
61	  MatrixJotaiStore.set(syncService, null);
62	  MatrixJotaiStore.set(ignoredUsers, null);
63	  MatrixJotaiStore.set(verificationStatus, "idle");
64	  MatrixJotaiStore.set(verificationEmojis, null);
65	  MatrixJotaiStore.set(verificationSenderName, null);
66	};
